function drawCheckersBoard(state,player,selectedFrom,onCell){
 const board=document.createElement('div');board.className='checkers-board';const legal=VladyerikDamas.legalMoves(state,player),side=VladyerikDamas.sideFor(player);
 for(let cell=0;cell<VladyerikDamas.CELLS;cell++){
  const row=Math.floor(cell/VladyerikDamas.SIZE),col=cell%VladyerikDamas.SIZE,piece=state.board[cell],button=document.createElement('button');button.type='button';button.className='checkers-cell '+((row+col)%2?'dark':'light');
  const targets=legal.filter(m=>m.from===selectedFrom),target=targets.find(m=>m.to===cell);
  if(legal.some(m=>m.from===cell))button.classList.add(legal.some(m=>m.captured!==null)?'capture-origin':'can-move');
  if(cell===selectedFrom)button.classList.add('selected');if(target){button.classList.add('legal-target');if(target.captured!==null)button.classList.add('capture-target')}
  if(piece){const token=document.createElement('span');token.className='checkers-piece '+(piece>0?'red':'black')+(Math.abs(piece)===2?' king':'')+((state.capturedThisTurn||[]).includes(cell)?' captured':'');button.append(token)}
  const coord=String.fromCharCode(65+row)+(col+1);button.setAttribute('aria-label',coord+(piece?' '+(piece>0?'roja':'negra')+(Math.abs(piece)===2?' dama':' ficha'):' casilla'));
  button.disabled=state.winner!==null||state.turn!==player;button.onclick=()=>onCell(cell);board.append(button)
 }
 return board
}
