$('backToGames').onclick=chooseMenu;$('modeSolo').onclick=()=>{beginSelectedMode();const setup=({'batalla-naval':'soloSetup',damas:'checkersSetup','ludo-matic':'ludoSetup','tutti-frutti':'wordSetup',basta:'wordSetup',estanciero:'estancieroSetup'})[selected];$(setup).scrollIntoView({behavior:'smooth',block:'center'})};$('modeOnline').onclick=()=>startOnline(selected);$('onlineMenu').onclick=chooseMenu;$('startSolo').onclick=beginSolo;$('cancelSolo').onclick=()=>$('soloSetup').classList.add('hidden');$('startDamas').onclick=beginDamasSolo;$('cancelDamas').onclick=()=>$('checkersSetup').classList.add('hidden');$('startLudo').onclick=beginLudoSolo;$('cancelLudo').onclick=()=>$('ludoSetup').classList.add('hidden');$('startWordSolo').onclick=startWordSolo;$('cancelWordSolo').onclick=()=>$('wordSetup').classList.add('hidden');$('startEstancieroSolo').onclick=startEstancieroSolo;$('cancelEstancieroSolo').onclick=()=>$('estancieroSetup').classList.add('hidden');
