async function heartbeat(){const nickname=$('nick').value.trim();if(nickname.length<2){announce('Escribí un apodo de al menos dos caracteres para conectarte.');$('join').disabled=false;return}if(busy)return;busy=true;$('join').disabled=true;localStorage.setItem('vladi_online_nick',nickname);try{const data=await fetch('/api/presence',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({nickname,token}),cache:'no-store'}).then(async res=>{const x=await res.json();if(!res.ok)throw new Error(x.error||'No se pudo conectar.');return x});connected=true;players=data.players||[];rooms=data.rooms||[];invitations=data.invitations||[];myRoom=data.selfRoom||null;$('roomControls').classList.remove('hidden');$('join').textContent='Conectado';$('join').disabled=true;announce('Conectado al lobby. Elegí un rival o creá una sala.');drawPlayers();drawRooms();drawInvites();updateRoom();if(params.has('room')&&!myRoom)await joinRoom(params.get('room'),params.get('code')||'')}catch(error){announce(error.message);$('join').disabled=false}finally{busy=false}}
async function createRoom(){if(busy||!catalogue.some(item=>item[0]===selected&&item[4]))return;busy=true;try{myRoom=await request('/rooms',{game:selected,capacity:maxPlayers(selected)>2?Number($('roomCapacity').value):2,visibility:$('visibility').value});lastRoomVersion=-1;updateRoom();announce('Sala creada. Compartí el enlace o invitá a otros jugadores.');await refresh()}catch(error){announce(error.message)}finally{busy=false}}
async function joinRoom(roomId,code){if(busy)return;busy=true;try{myRoom=await request('/rooms/'+roomId+'/join',{code});lastRoomVersion=-1;history.replaceState(null,'','/?room='+roomId+(code?'&code='+encodeURIComponent(code):'')+'&game='+encodeURIComponent(myRoom.game));updateRoom();await refresh();announce(myRoom.state==='playing'?'Partida iniciada.':'Entraste a la sala.')}catch(error){announce(error.message)}finally{busy=false}}
async function sendInvite(playerId){if(busy)return;busy=true;try{const result=await request('/invitations',{to:playerId,game:selected,capacity:maxPlayers(selected)>2?Number($('roomCapacity').value):2});myRoom=result.room;updateRoom();announce('Invitación a '+gameName(selected)+' enviada a '+result.nickname+'.');await refresh()}catch(error){announce(error.message)}finally{busy=false}}
async function respond(inviteId,accept){if(busy)return;busy=true;try{if(accept){myRoom=await request('/invitations/'+inviteId+'/respond',{accept:true});lastRoomVersion=-1;updateRoom();announce('Invitación aceptada. ¡A jugar!')}else{await request('/invitations/'+inviteId+'/respond',{accept:false});announce('Invitación rechazada.')}await refresh()}catch(error){announce(error.message)}finally{busy=false}}
async function shoot(cell){if(!myRoom||busy)return;busy=true;playSound('fire');try{myRoom=await request('/rooms/'+myRoom.room+'/action',{cell});lastRoomVersion=-1;updateRoom();announce(myRoom.state==='finished'?(myRoom.winner?'¡Ganaste la partida!':'Tu rival ganó la partida.'):'Disparo enviado.')}catch(error){announce(error.message);await refresh()}finally{busy=false}}
async function leaveRoom(){if(!myRoom||busy)return;busy=true;try{await request('/rooms/'+myRoom.room+'/leave',{});myRoom=null;lastRoomVersion=-1;if(wordClockInterval){clearInterval(wordClockInterval);wordClockInterval=null}$('gameScreen').replaceChildren();$('gameScreen').classList.add('hidden');$('lobbyView').classList.remove('hidden');history.replaceState(null,'','/');updateRoom();await refresh();announce('Saliste de la sala.')}catch(error){announce(error.message)}finally{busy=false}}
$('join').onclick=heartbeat;$('create').onclick=createRoom;$('leave').onclick=leaveRoom;$('refresh').onclick=refresh;
if(params.has('room'))startOnline(params.get('game')||'batalla-naval');
